<script setup>
import { ref,computed,watch,onBeforeUnmount } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { api,state,notify,speak,refresh } from '../api'
import Icon from '../components/Icon.vue'
const route=useRoute(),router=useRouter()
const search=ref(''),status=ref('all'),level=ref(''),page=ref(1),words=ref([]),total=ref(0),loading=ref(false),error=ref('')
const topic=computed(()=>state.topics.find(t=>t.id===Number(route.query.topic)))
const pages=computed(()=>Math.ceil(total.value/24))
let timer,revision=0
async function load(){const version=++revision;loading.value=true;error.value='';try{const params=new URLSearchParams({q:search.value,status:status.value,level:level.value,page:page.value});if(topic.value)params.set('topic_id',topic.value.id);const data=await api('/words?'+params);if(version===revision){words.value=data.items;total.value=data.total}}catch(e){if(version===revision)error.value=e.message}finally{if(version===revision)loading.value=false}}
watch([search,status,level,()=>route.query.topic],()=>{page.value=1;clearTimeout(timer);timer=setTimeout(load,180)})
watch(page,load)
load()
onBeforeUnmount(()=>{clearTimeout(timer);revision++})
async function bookmark(word){if(word.pending)return;word.pending=true;try{await api(`/words/${word.id}/bookmark`,{method:'PUT',body:JSON.stringify({saved:!word.saved})});word.saved=!word.saved;notify(word.saved?'Đã lưu vào từ yêu thích':'Đã bỏ lưu từ');if(status.value==='saved')await load()}catch(e){notify(e.message)}finally{word.pending=false}}
const showAdd=ref(false),adding=ref(false),addError=ref('')
const form=ref({topic_id:topic.value?.id||state.topics[0]?.id,term:'',meaning:'',example:'',level:'A1'})
async function add(){adding.value=true;addError.value='';try{await api('/words',{method:'POST',body:JSON.stringify(form.value)});showAdd.value=false;form.value={...form.value,term:'',meaning:'',example:''};await refresh();await load();notify('Đã thêm từ vựng của bạn')}catch(e){addError.value=e.message}finally{adding.value=false}}
</script>
<template><div class="page"><div class="page-heading"><div><div class="eyebrow">{{topic ? topic.category.toUpperCase() : 'BỘ SƯU TẬP CỦA BẠN'}}</div><h1>{{topic?.name || 'Kho từ vựng'}}</h1><p>{{topic?.description || 'Tra cứu, nghe và lưu những từ bạn muốn ghi nhớ.'}}</p></div><div class="heading-actions"><button class="btn outline" @click="showAdd=true"><Icon name="Plus" :size="17"/>Thêm từ</button><RouterLink :to="topic ? `/study?topic=${topic.id}` : '/study'" class="btn primary"><Icon name="Layers" :size="17"/>Học flashcard</RouterLink></div></div>
<div class="library-filters"><label class="search-field grow"><Icon name="Search" :size="19"/><input v-model="search" placeholder="Tìm từ tiếng Anh hoặc nghĩa tiếng Việt…" aria-label="Tìm từ vựng"/></label><select :value="route.query.topic || ''" aria-label="Chọn chủ đề" @change="router.replace({path:'/words',query:$event.target.value ? {topic:$event.target.value} : {}})"><option value="">Tất cả chủ đề</option><option v-for="t in state.topics" :value="t.id" :key="t.id">{{t.name}}</option></select><select v-model="level" aria-label="Lọc mức độ"><option value="">Mọi mức độ</option><option>A1</option><option>A2</option><option>B1</option><option>B2</option></select></div>
<div class="toolbar"><div class="tabs"><button v-for="[value,label] in [['all','Tất cả'],['new','Chưa học'],['learned','Đã học'],['mastered','Đã nhớ vững'],['saved','Đã lưu']]" :key="value" :class="{selected:status===value}" @click="status=value">{{label}}</button></div><span class="result-count">{{total}} kết quả</span></div>
<div v-if="error" class="error-panel" role="alert">{{error}}<button class="btn outline" @click="load">Thử lại</button></div><div v-else-if="loading" class="loading-panel">Đang tìm từ vựng…</div><div v-else-if="!words.length" class="empty-state"><Icon name="BookOpen" :size="36"/><h3>Chưa có từ ở đây</h3><p>Thử đổi bộ lọc hoặc thêm từ bạn muốn học.</p></div>
<div v-else class="word-grid"><article v-for="word in words" :key="word.id" class="word-card"><div class="word-top"><span class="word-topic" :style="{background:word.topic_color}">{{word.topic_name}}</span><button class="icon-button" :class="{saved:word.saved}" :disabled="word.pending" :aria-label="word.saved ? 'Bỏ lưu '+word.term : 'Lưu '+word.term" :aria-pressed="!!word.saved" @click="bookmark(word)"><Icon name="Bookmark" :size="19"/></button></div><div class="word-term"><h3>{{word.term}}</h3><button class="icon-button" :aria-label="'Nghe '+word.term" @click="speak(word.term)"><Icon name="Volume2" :size="19"/></button></div><p class="word-meaning">{{word.meaning}}</p><p class="word-example">“{{word.example}}”</p><div class="word-bottom"><span class="level">{{word.level}}</span><span :class="['word-status',word.last_rating ? 'learned' : '']"><span></span>{{word.repetitions>=3 && word.interval_days>=7 ? 'Đã nhớ vững' : word.last_rating ? 'Đang học' : 'Từ mới'}}</span></div></article></div>
<div v-if="pages>1" class="pagination"><button class="btn outline" :disabled="page<=1 || loading" @click="page--"><Icon name="ChevronLeft" :size="16"/>Trước</button><span>Trang {{page}} / {{pages}}</span><button class="btn outline" :disabled="page>=pages || loading" @click="page++">Sau<Icon name="ChevronRight" :size="16"/></button></div>
<div v-if="showAdd" class="modal-overlay" @click.self="showAdd=false" @keydown.esc="showAdd=false"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="add-title"><div class="section-heading"><h2 id="add-title">Thêm từ của bạn</h2><button class="icon-button" aria-label="Đóng" @click="showAdd=false"><Icon name="X"/></button></div><p class="muted">Lưu những từ bạn gặp trong cuộc sống vào bộ từ riêng.</p><form @submit.prevent="add"><label>Chủ đề<select v-model.number="form.topic_id"><option v-for="t in state.topics" :key="t.id" :value="t.id">{{t.name}}</option></select></label><label>Từ hoặc cụm từ tiếng Anh<input v-model="form.term" required maxlength="100" placeholder="Ví dụ: grab a coffee"/></label><label>Nghĩa tiếng Việt<input v-model="form.meaning" required maxlength="200" placeholder="Ví dụ: đi uống cà phê"/></label><label>Câu ví dụ<input v-model="form.example" required maxlength="300" placeholder="Let's grab a coffee after work."/></label><label>Mức độ<select v-model="form.level"><option>A1</option><option>A2</option><option>B1</option><option>B2</option></select></label><p v-if="addError" class="form-error" role="alert">{{addError}}</p><button class="btn primary full" :disabled="adding">{{adding ? 'Đang lưu…' : 'Thêm vào kho từ'}}</button></form></section></div>
</div></template>
